/*
 * A261866  Expansion of (G(-x) / chi(-x))^2 in powers of x where chi() is a
 *          Ramanujan theta function and G() is a Rogers-Ramanujan function.
 * https://oeis.org/A261866
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the Euler transform of the period‑20
 *            sequence [0, 2, 2, 2, 2, 2, 2, 0, 0, 0, 0, 0, 2, 2, 2, 2, 2, 2,
 *            0, 0]. That is, a(n) is the coefficient of x^n in ∏_{k≥1} (1 −
 *            x^k)^{−b(k)}, where b(k) equals 2 for k ≡
 *            2,3,4,5,6,7,13,14,15,16,17,18 (mod 20) and 0 otherwise. The
 *            implementa...
 * Range:     u8 n <= 14, u16 n <= 36, u32 n <= 104, u64 n <= 339,
 *            u128 n <= 1194, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

static const int period20[20] = {
    0, /* 1 */
    2, /* 2 */
    2, /* 3 */
    2, /* 4 */
    2, /* 5 */
    2, /* 6 */
    2, /* 7 */
    0, /* 8 */
    0, /* 9 */
    0, /*10 */
    0, /*11 */
    0, /*12 */
    2, /*13 */
    2, /*14 */
    2, /*15 */
    2, /*16 */
    2, /*17 */
    2, /*18 */
    0, /*19 */
    0  /*20 */
};

seq_t a(idx_t n)
{
    size_t N = (size_t)n;
    seq_t *dp = (seq_t *)calloc(N + 1, sizeof(seq_t));
    if (!dp) return 0;            /* allocation failure – unlikely in test harness */
    dp[0] = (seq_t)1;

    for (size_t k = 1; k <= N; ++k) {
        int exponent = period20[(k - 1) % 20];
        if (exponent == 2) {
            /* first copy of the factor (1 - x^k)^(-1) */
            for (size_t m = k; m <= N; ++m) {
                dp[m] = dp[m] + dp[m - k];
            }
            /* second copy – results in exponent 2 */
            for (size_t m = k; m <= N; ++m) {
                dp[m] = dp[m] + dp[m - k];
            }
        }
    }

    seq_t res = dp[N];
    free(dp);
    return res;
}
